-- Emergency access-policy rollback. Reopens the original public access; do not run routinely.
begin;
do $$ declare p record; begin for p in select policyname from pg_policies where schemaname='public' and tablename='song_requests' loop execute format('drop policy %I on public.%I',p.policyname,'song_requests'); end loop; end $$;
revoke all on public."song_requests" from anon, authenticated;
grant DELETE, INSERT, SELECT, UPDATE on public."song_requests" to anon;
grant DELETE, INSERT, SELECT, UPDATE on public."song_requests" to authenticated;
do $$ declare p record; begin for p in select policyname from pg_policies where schemaname='public' and tablename='private_messages' loop execute format('drop policy %I on public.%I',p.policyname,'private_messages'); end loop; end $$;
revoke all on public."private_messages" from anon, authenticated;
grant DELETE, INSERT, SELECT, UPDATE on public."private_messages" to anon;
grant DELETE, INSERT, SELECT, UPDATE on public."private_messages" to authenticated;
do $$ declare p record; begin for p in select policyname from pg_policies where schemaname='public' and tablename='songs_backup' loop execute format('drop policy %I on public.%I',p.policyname,'songs_backup'); end loop; end $$;
revoke all on public."songs_backup" from anon, authenticated;
grant DELETE, INSERT, SELECT, UPDATE on public."songs_backup" to anon;
grant DELETE, INSERT, SELECT, UPDATE on public."songs_backup" to authenticated;
do $$ declare p record; begin for p in select policyname from pg_policies where schemaname='public' and tablename='song_events' loop execute format('drop policy %I on public.%I',p.policyname,'song_events'); end loop; end $$;
revoke all on public."song_events" from anon, authenticated;
grant DELETE, INSERT, SELECT, UPDATE on public."song_events" to anon;
grant DELETE, INSERT, SELECT, UPDATE on public."song_events" to authenticated;
do $$ declare p record; begin for p in select policyname from pg_policies where schemaname='public' and tablename='song_analytics' loop execute format('drop policy %I on public.%I',p.policyname,'song_analytics'); end loop; end $$;
revoke all on public."song_analytics" from anon, authenticated;
grant DELETE, INSERT, SELECT, UPDATE on public."song_analytics" to anon;
grant DELETE, INSERT, SELECT, UPDATE on public."song_analytics" to authenticated;
do $$ declare p record; begin for p in select policyname from pg_policies where schemaname='public' and tablename='song_likes' loop execute format('drop policy %I on public.%I',p.policyname,'song_likes'); end loop; end $$;
revoke all on public."song_likes" from anon, authenticated;
grant DELETE, INSERT, SELECT, UPDATE on public."song_likes" to anon;
grant DELETE, INSERT, SELECT, UPDATE on public."song_likes" to authenticated;
create policy "Allow admin read private messages" on public."private_messages" for SELECT to "anon" using (true);
create policy "Allow public delete private messages" on public."private_messages" for DELETE to "anon" using (true);
create policy "Allow public insert private messages" on public."private_messages" for INSERT to "anon" with check (true);
create policy "Allow public inserts messages" on public."private_messages" for INSERT to "anon" with check (true);
create policy "Allow public read private messages" on public."private_messages" for SELECT to "anon" using (true);
create policy "Allow public update private messages" on public."private_messages" for UPDATE to "anon" using (true) with check (true);
create policy "Allow public insert song analytics" on public."song_analytics" for INSERT to "anon" with check (true);
create policy "Allow public read song analytics" on public."song_analytics" for SELECT to "anon" using (true);
create policy "Allow public update song analytics" on public."song_analytics" for UPDATE to "anon" using (true) with check (true);
create policy "public can insert song analytics" on public."song_analytics" for INSERT to "anon", "authenticated" with check (true);
create policy "public can read song analytics" on public."song_analytics" for SELECT to "anon", "authenticated" using (true);
create policy "public can update song analytics" on public."song_analytics" for UPDATE to "anon", "authenticated" using (true) with check (true);
create policy "public can insert song events" on public."song_events" for INSERT to "anon", "authenticated" with check (true);
create policy "public can read song events" on public."song_events" for SELECT to "anon", "authenticated" using (true);
create policy "Allow public insert song likes" on public."song_likes" for INSERT to "anon" with check (true);
create policy "Allow public read song likes" on public."song_likes" for SELECT to "anon" using (true);
create policy "Allow public update song likes" on public."song_likes" for UPDATE to "anon" using (true) with check (true);
create policy "Allow admin read song requests" on public."song_requests" for SELECT to "anon" using (true);
create policy "Allow public delete song requests" on public."song_requests" for DELETE to "anon" using (true);
create policy "Allow public insert song requests" on public."song_requests" for INSERT to "anon" with check (true);
create policy "Allow public inserts" on public."song_requests" for INSERT to "anon" with check (true);
create policy "Allow public read song requests" on public."song_requests" for SELECT to "anon" using (true);
create policy "Allow public update song requests" on public."song_requests" for UPDATE to "anon" using (true) with check (true);
commit;
